{
  "name": "Serre Vintage 70's",
  "description": "Une application de gestion de serre connectée au style rétro des années 70, offrant un suivi de température et des conseils de culture intelligents via Gemini.",
  "requestFramePermissions": []
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface TemperatureData {
  inside: number;
  outside: number;
  timestamp: string;
}

export interface Recommendation {
  action: string;
  explanation: string;
}

export enum DeviceStatus {
  ONLINE = 'ONLINE',
  OFFLINE = 'OFFLINE',
}

import { GoogleGenAI, Type } from "@google/genai";

const API_KEY = process.env.API_KEY || "";
const ai = new GoogleGenAI({ apiKey: API_KEY });

export async function getGreenhouseAdvice(insideTemp: number, outsideTemp: number) {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Actuellement dans ma serre : température intérieure ${insideTemp}°C, température extérieure ${outsideTemp}°C. 
      Donne-moi un conseil court et vintage (style années 70) pour prendre soin de mes plantes aujourd'hui.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            action: { type: Type.STRING, description: "L'action recommandée" },
            explanation: { type: Type.STRING, description: "Pourquoi cette action est importante" }
          },
          required: ["action", "explanation"]
        }
      }
    });

    return JSON.parse(response.text.trim());
  } catch (error) {
    console.error("Error fetching Gemini advice:", error);
    return {
      action: "Reste cool !",
      explanation: "L'API est un peu fatiguée, mais garde un oeil sur tes tomates, man."
    };
  }
}

import React from 'react';

