      <div className="flex items-center gap-3 mb-4">
        {icon && <span className="text-2xl">{icon}</span>}
        <h2 className="retro-title text-xl uppercase tracking-wider">{title}</h2>
      </div>
      <div className="font-bold text-lg">
        {children}
      </div>
    </div>
