export default TemperatureDisplay;

import React, { useState, useEffect, useCallback } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend } from 'recharts';
import { getGreenhouseAdvice } from './services/geminiService';
import { TemperatureData, Recommendation } from './types';
import RetroCard from './components/RetroCard';
import TemperatureDisplay from './components/TemperatureDisplay';

// Mock historical data
const INITIAL_HISTORY: TemperatureData[] = Array.from({ length: 12 }, (_, i) => ({
  timestamp: `${i * 2}h`,
  inside: 18 + Math.random() * 10,
  outside: 12 + Math.random() * 8,
}));

const App: React.FC = () => {
  const [currentTemps, setCurrentTemps] = useState<TemperatureData>({
    inside: 24.5,
    outside: 16.2,
    timestamp: 'Maintenant'
  });
  const [history, setHistory] = useState<TemperatureData[]>(INITIAL_HISTORY);
  const [advice, setAdvice] = useState<Recommendation | null>(null);
  const [loadingAdvice, setLoadingAdvice] = useState(false);

  // Update temperatures randomly every 10 seconds for simulation
  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentTemps(prev => ({
        ...prev,
        inside: prev.inside + (Math.random() - 0.5),
        outside: prev.outside + (Math.random() - 0.5),
      }));
    }, 10000);
    return () => clearInterval(interval);
  }, []);

  const fetchAdvice = useCallback(async () => {
    setLoadingAdvice(true);
    const result = await getGreenhouseAdvice(currentTemps.inside, currentTemps.outside);
    setAdvice(result);
    setLoadingAdvice(false);
  }, [currentTemps.inside, currentTemps.outside]);

  useEffect(() => {
    fetchAdvice();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div className="min-h-screen p-4 md:p-8 max-w-5xl mx-auto">
      {/* Header */}
      <header className="mb-12 text-center">
        <div className="inline-block p-4 retro-border bg-mustard retro-card mb-4">
          <h1 className="retro-title text-4xl md:text-6xl text-retroBrown uppercase leading-none">
            Ma Serre Disco
          </h1>
        </div>
        <p className="text-xl italic font-bold text-burntOrange">
          Cultiver avec style depuis 1974
        </p>
      </header>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        {/* Left Column: Temperatures */}
        <section>
          <RetroCard title="Températures Actuelles" bgColor="bg-cream" icon="🌡️">
            <div className="grid grid-cols-2 gap-4 bg-white/50 p-4 rounded-xl border-2 border-retroBrown shadow-inner">
              <TemperatureDisplay label="Intérieur" value={currentTemps.inside} color="text-avocado" />
              <TemperatureDisplay label="Extérieur" value={currentTemps.outside} color="text-burntOrange" />
            </div>
            <div className="mt-4 text-center text-sm italic">
              Dernière synchronisation : {new Date().toLocaleTimeString()}
            </div>
          </RetroCard>

          <RetroCard title="Le Gourou de la Serre" bgColor="bg-mustard" icon="📻">
            {loadingAdvice ? (
              <div className="flex items-center justify-center p-4">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-retroBrown"></div>
                <span className="ml-3 italic uppercase">Transmission en cours...</span>
              </div>
            ) : advice ? (
              <div className="space-y-3">
                <div className="bg-white p-3 retro-border">
                  <p className="text-avocado font-black uppercase text-xl mb-1">💡 {advice.action}</p>
                  <p className="text-sm leading-relaxed">{advice.explanation}</p>
                </div>
                <button 
                  onClick={fetchAdvice}
                  className="w-full py-2 bg-burntOrange text-white retro-border retro-button uppercase tracking-widest font-bold"
                >
                  Demander une nouvelle vibe
                </button>
              </div>
            ) : null}
          </RetroCard>
        </section>

        {/* Right Column: History Chart */}
        <section>
          <RetroCard title="Évolution Temporelle" bgColor="bg-white" icon="📈">
            <div className="h-64 md:h-80 w-full mt-2">
              <ResponsiveContainer width="100%" height="100%">
                <LineChart data={history}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#ccc" />
                  <XAxis dataKey="timestamp" stroke="#2D241E" />
                  <YAxis stroke="#2D241E" />
                  <Tooltip 
                    contentStyle={{ backgroundColor: '#F4EBD0', border: '2px solid #2D241E', borderRadius: '0' }}
                  />
                  <Legend />
                  <Line 
                    type="monotone" 
                    dataKey="inside" 
                    stroke="#568203" 
                    strokeWidth={4} 
                    dot={{ r: 6, fill: '#568203' }} 
                    name="Serre (°C)"
                  />
                  <Line 
                    type="monotone" 
                    dataKey="outside" 
                    stroke="#D16002" 
                    strokeWidth={4} 
                    dot={{ r: 6, fill: '#D16002' }} 
                    name="Jardin (°C)"
                  />
                </LineChart>
              </ResponsiveContainer>
            </div>
          </RetroCard>

          <RetroCard title="Statut du Système" bgColor="bg-avocado" icon="🔌">
            <div className="flex items-center justify-between text-white">
              <span className="uppercase tracking-widest font-black">Sensors Online</span>
              <div className="flex gap-2">
                <div className="h-4 w-4 bg-yellow-400 rounded-full animate-pulse shadow-lg"></div>
                <div className="h-4 w-4 bg-yellow-400 rounded-full animate-pulse delay-75 shadow-lg"></div>
              </div>
            </div>
            <p className="text-xs text-white/80 mt-2 uppercase">Liaison satellite établie via Telstar</p>
          </RetroCard>
        </section>
      </div>

      {/* Footer Pattern */}
      <footer className="mt-16 text-center space-y-4">
        <div className="flex justify-center space-x-2">
          <div className="h-8 w-1/4 bg-burntOrange"></div>
          <div className="h-8 w-1/4 bg-mustard"></div>
          <div className="h-8 w-1/4 bg-avocado"></div>
          <div className="h-8 w-1/4 bg-retroBrown"></div>
        </div>
        <p className="text-xs font-bold uppercase tracking-widest opacity-50">
          Greenhouse Management System v1.9.7.5
        </p>
      </footer>
    </div>
  );
};

export default App;

