import React, { useState, useEffect, useCallback } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend } from 'recharts';
import { getGreenhouseAdvice } from './services/geminiService';
import { TemperatureData, Recommendation } from './types';
import RetroCard from './components/RetroCard';
import TemperatureDisplay from './components/TemperatureDisplay';

const INITIAL_HISTORY: TemperatureData[] = Array.from({ length: 12 }, (_, i) => ({
  timestamp: `${i * 2}h`,
  inside: 22 + Math.random() * 5,
  outside: 15 + Math.random() * 10,
}));

const App: React.FC = () => {
  const [currentTemps, setCurrentTemps] = useState<TemperatureData>({
    inside: 24.5,
    outside: 16.2,
    timestamp: 'Maintenant'
  });
  const [history, setHistory] = useState<TemperatureData[]>(INITIAL_HISTORY);
  const [advice, setAdvice] = useState<Recommendation | null>(null);
  const [loadingAdvice, setLoadingAdvice] = useState(false);

  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentTemps(prev => {
        const newInside = prev.inside + (Math.random() - 0.5);
        const newOutside = prev.outside + (Math.random() - 0.5);
        return {
          ...prev,
          inside: newInside,
          outside: newOutside,
        };
      });
    }, 5000);
    return () => clearInterval(interval);
  }, []);

  const fetchAdvice = useCallback(async () => {
    setLoadingAdvice(true);
    const result = await getGreenhouseAdvice(currentTemps.inside, currentTemps.outside);
    setAdvice(result);
    setLoadingAdvice(false);
  }, [currentTemps.inside, currentTemps.outside]);

  useEffect(() => {
    fetchAdvice();
  }, []);

  return (
    <div className="min-h-screen p-4 md:p-12 max-w-6xl mx-auto">
      {/* Header */}
      <header className="mb-12 text-center relative">
        <div className="inline-block p-1 bg-white/20 rounded-[40px] backdrop-blur-md border border-white/50 shadow-xl mb-4">
          <div className="px-10 py-6 rounded-[35px] bg-gradient-to-br from-white/60 to-white/20">
            <h1 className="text-5xl md:text-7xl font-black title-gradient uppercase tracking-tighter leading-none italic">
              Eco-Sphere 2000
            </h1>
          </div>
        </div>
        <p className="text-lg font-bold text-sky-700 tracking-widest uppercase opacity-80">
          Greenhouse OS // Next-Gen Agriculture
        </p>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
        {/* Left: Realtime Status */}
        <div className="lg:col-span-5 space-y-6">
          <RetroCard title="Capteurs Biométriques" icon="🧊">
            <div className="grid grid-cols-2 gap-4">
              <TemperatureDisplay label="Serre" value={currentTemps.inside} color="text-avocado" />
              <TemperatureDisplay label="Environnement" value={currentTemps.outside} color="text-burntOrange" />
            </div>
            <div className="mt-6 flex items-center justify-between text-[10px] font-black uppercase text-sky-800/60 tracking-widest bg-white/20 p-2 rounded-full border border-white/40">
              <span>Flux de données: Synchronisé</span>
              <span className="flex h-2 w-2 rounded-full bg-emerald-400 animate-pulse"></span>
            </div>
          </RetroCard>

          <RetroCard title="Module IA d'Optimisation" icon="🤖">
            {loadingAdvice ? (
              <div className="flex flex-col items-center justify-center py-8">
                <div className="w-12 h-12 border-4 border-sky-200 border-t-sky-500 rounded-full animate-spin"></div>
                <span className="mt-4 text-[10px] font-black uppercase tracking-[0.3em] text-sky-600 animate-pulse">Analyse en cours...</span>
              </div>
            ) : advice ? (
              <div className="space-y-4">
                <div className="bg-white/40 p-4 rounded-2xl border border-white/60 shadow-inner">
                  <p className="text-emerald-600 font-black uppercase text-sm mb-2 tracking-wider flex items-center">
                    <span className="mr-2">⚡</span> {advice.action}
                  </p>
                  <p className="text-sm leading-relaxed text-slate-700 italic">"{advice.explanation}"</p>
                </div>
                <button 
