                    activeDot={{ r: 8, strokeWidth: 0 }}
                    name="Extérieur"
                  />
                </LineChart>
              </ResponsiveContainer>
            </div>
          </RetroCard>

          <div className="grid grid-cols-2 gap-4">
             <div className="y2k-glass p-4 flex flex-col items-center justify-center text-center">
                <span className="text-[9px] font-black uppercase tracking-widest text-sky-800 mb-1">Signal</span>
                <div className="flex space-x-1">
                  {[1,2,3,4,5].map(i => <div key={i} className="w-1 h-4 bg-sky-400/40 rounded-full overflow-hidden relative"><div className="absolute bottom-0 left-0 right-0 bg-sky-600" style={{height: `${i*20}%`}}></div></div>)}
                </div>
             </div>
             <div className="y2k-glass p-4 flex flex-col items-center justify-center text-center">
                <span className="text-[9px] font-black uppercase tracking-widest text-emerald-800 mb-1">Système</span>
                <span className="text-xs font-bold text-emerald-600 animate-pulse">OPTIMAL</span>
             </div>
          </div>
        </div>
      </div>

      {/* Footer */}
      <footer className="mt-16 pb-8 border-t border-white/40 pt-8 text-center">
        <p className="text-[10px] font-black uppercase tracking-[0.4em] text-sky-900/40">
          © 2000-2005 Eco-Sphere Systems Inc. // Designed for the Millennium
        </p>
      </footer>
    </div>
  );
};

export default App;

